contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 val) public payable {
        require(true);

        bool reverted1;
        c.SetMinSum(val); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted1 = true; } else { reverted1 = false; }

        uint256 afterFirst = c.MinSum(); if (__ESBMC_reverted()) return;

        assert(!reverted1 && afterFirst == val);
    }

    receive() external payable {}
}

