contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MONEY_BOX c;

    function setUp() public {
        c = new MONEY_BOX();
    }

    function _run(uint256 val) internal {
        vm.assume(true);
        bool reverted1;
        try c.SetMinSum(val) { reverted1 = false; } catch { reverted1 = true; }
        uint256 afterFirst;
        try c.MinSum() returns (uint256 __r) { afterFirst = __r; } catch { return; }
        assertTrue(!reverted1 && afterFirst == val);
    }

    function testFuzz_run(uint256 val) public {
        _run(val);
    }

    receive() external payable {}
}
